SELECT
d.dealer_id,
d.dealer_name,
d.dealer_email,
d.dealer_number_of_favorites,
d.is_internal,
DATETIME(d.dealer_created, cmt.country_timezone) as dealer_created,
DATETIME(d.dealer_last_modified, cmt.country_timezone) as dealer_last_modified,
d.dealer_company_name,
COALESCE((select count(distinct b.auction_id) from `{{params.project_name}}.staging.Bids` b where b.dealer_id = d.dealer_id), 0) as number_of_auctions,
COALESCE((select count(a.auction_id) from `{{params.project_name}}.staging.Auctions` a where a.winner_dealer_id = d.dealer_id), 0) as number_of_win_auctions,
COALESCE((select count(b.bid_id) from `{{params.project_name}}.staging.Bids` b where b.dealer_id = d.dealer_id), 0) as number_of_bids,
/* NULL as last_login, Needs MixPanel data */
(select max(DATETIME(b.bid_datetime, cmt.country_timezone)) from `{{params.project_name}}.staging.Bids` b where b.dealer_id = d.dealer_id) as last_bid_placed,
DATETIME(d.deleted_at, cmt.country_timezone) as deleted_at,
d.country_id,
d.dealer_status,
d.dealer_onboarding_agent_id,
d.dealer_onboarding_agent_name,
d.dealer_manager_id,
d.dealer_manager_name,
d.dealer_company_legal_name,
d.dealer_company_legal_tax,
d.dealer_tax_id,
d.dealer_address,
d.dealer_city,
d.dealer_phone,
d.dealer_zipecode as dealer_zip_code, /* TODO: Fix typo in staging table*/
d.max_amount_of_bids,
d.blocked_reason,
d.dealer_category,
d.dealer_size,
d.registration_id,
d.tax_office,
d.authorized_pickup_persons,
d.payment_terms,
d.bank_details,
d.dealer_comments,
d.internal_id,
d.dealer_number,
/* TODO: Missing dealer_bid_limit */
d.dealer_login,
d.dealer_cms_status,
d.virtual_account,
d.system_set_credit_limit,
d.system_set_deposit_amount,
d.dealer_bid_manager,
d.meta_info
/* ,
d.business_category, 
d.person_type,
d.legal_representative_name */
FROM `{{params.project_name}}.staging.Dealers` d
INNER JOIN `{{params.project_name}}.staging.CountryMetadata` cmt using (country_id)
where d.dealer_last_modified >= '{{params.start_ts}}' and d.dealer_last_modified < '{{params.end_ts}}'